  CREATE TABLE "SYSTEM"."RUTAS" 
   (	"ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ZONA_ID" NUMBER NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(200 BYTE) NOT NULL ENABLE, 
	"DESCRIPCION" VARCHAR2(1000 BYTE), 
	"DISTANCIA_KM" NUMBER(7,2), 
	"DIFICULTAD" VARCHAR2(30 BYTE), 
	"TIPO" VARCHAR2(30 BYTE), 
	"DESNIVEL_POSITIVO_M" NUMBER(7,2), 
	"DESNIVEL_NEGATIVO_M" NUMBER(7,2), 
	"ALTITUD_MIN_M" NUMBER(7,2), 
	"ALTITUD_MAX_M" NUMBER(7,2), 
	"TIEMPO_MINUTOS" NUMBER(5,0), 
	"FUENTE" VARCHAR2(100 BYTE), 
	"FUENTE_ID" VARCHAR2(100 BYTE), 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"LATITUD" NUMBER(10,7), 
	"LONGITUD" NUMBER(10,7), 
	 CONSTRAINT "CK_RUTAS_DISTANCIA" CHECK (distancia_km IS NULL OR distancia_km >= 0) ENABLE, 
	 CONSTRAINT "CK_RUTAS_DIFICULTAD" CHECK (
            dificultad IS NULL
            OR dificultad IN (
                'Muy fácil',
                'Fácil',
                'Moderada',
                'Difícil',
                'Muy difícil'
            )
        ) ENABLE, 
	 CONSTRAINT "CK_RUTAS_TIPO" CHECK (
            tipo IS NULL
            OR tipo IN (
                'Circular',
                'Lineal',
                'Ida y vuelta'
            )
        ) ENABLE, 
	 CONSTRAINT "CK_RUTAS_TIEMPO" CHECK (tiempo_minutos IS NULL OR tiempo_minutos > 0) ENABLE, 
	 CONSTRAINT "PK_RUTAS" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "SYSTEM"  ENABLE, 
	 CONSTRAINT "CK_RUTAS_LATITUD" CHECK (LATITUD BETWEEN -90 AND 90) ENABLE, 
	 CONSTRAINT "CK_RUTAS_LONGITUD" CHECK (LONGITUD BETWEEN -180 AND 180) ENABLE, 
	 CONSTRAINT "FK_RUTAS_ZONA" FOREIGN KEY ("ZONA_ID")
	  REFERENCES "SYSTEM"."ZONAS" ("ID") ENABLE
   ) PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "SYSTEM" ;

  CREATE INDEX "SYSTEM"."IDX_RUTAS_ZONA" ON "SYSTEM"."RUTAS" ("ZONA_ID") 
  PCTFREE 10 INITRANS 2 MAXTRANS 255 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
